using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class LocalSecurityTests
{
 static readonly EntityId Site=new("site:castle");
 static WorldSession Start(){var records=new[]{NewGameWorldTests.Officer("created:leader"),NewGameWorldTests.Officer("created:one",StartTemplate.Retainer,lord:"created:leader"),NewGameWorldTests.Officer("created:two",StartTemplate.Retainer,lord:"created:leader"),NewGameWorldTests.Officer("created:three",StartTemplate.Retainer,lord:"created:leader")};var setup=NewGameWorldTests.Setup(records);return new(NewGameWorld.Create(setup.World,setup.Registered,"created:leader",inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:HouseSuccession.Policy,banditPolicy:LocalSecurity.Policy));}
 static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
 static void Assign(WorldSession s){foreach(var id in new[]{"created:one","created:two","created:three"})Good(s.ManageSecurity(new(new("request:guard/"+id.Replace(':','/')),SecurityAction.Assign,Site,new(id)),s.Revision));}
 [Fact]public void GuardsReserveRealPeopleTransferPayAndProtectWithoutDeletingBandits(){var s=Start();long before=NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl);Assign(s);var w=s.DiagnosticSnapshot();Assert.Equal(before-180,NewGameWork.Balance(w,s.PlayerControl));Assert.True(LocalSecurity.Protected(w,Site,0,s.Revision+1));Assert.True(BanditEncounter.Dangerous(w,Site));Assert.False(BanditEncounter.NeedsContact(w));Assert.Equal(ResultCode.AlreadyAccepted,s.ManageSecurity(new(new("request:guard/created/one"),SecurityAction.Assign,Site,new("created:one")),s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.ManageSecurity(new(new("request:again"),SecurityAction.Assign,Site,new("created:one")),s.Revision).Code);var move=TravelWorld.Move(w,"request:leave","sakai");Good(s.Submit(move,s.Revision));}
 [Fact]public void AbsenceStopsOnlyNewTransactionsAndActualGuardingReopensThem(){var s=Start();NewGameWorldTests.At(s,3*86400);Assert.True(LocalSecurity.MarketAvoided(s.DiagnosticSnapshot(),Site,s.Seconds,s.Revision+1));var input=new TradeInput(new("request:purchase"),TradeAction.Quote,Site,Destination:Site,Amount:1);Assert.Equal(ResultCode.NotAvailable,s.TradeRice(input,s.PlayerControl,s.Revision).Code);Assign(s);Assert.False(LocalSecurity.MarketAvoided(s.DiagnosticSnapshot(),Site,s.Seconds,s.Revision+1));Good(s.TradeRice(input,s.PlayerControl,s.Revision));}
 [Fact]public void ObservationDoesNotChangeRemotelyAndMidSaveHasSameExpiry(){var s=Start();Good(s.ManageSecurity(new(new("request:see"),SecurityAction.Observe,Site),s.Revision));var fact=LocalSecurity.Known(s.DiagnosticSnapshot(),Site);Assign(s);NewGameWorldTests.At(s,10);s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"security-save-"+Guid.NewGuid().ToString("N")),w.Definitions);store.Save(s,"manual",w.WorldId);var host=new WorldSessionHost(new WorldSession(w));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("manual"),host.Current,host.Current.Revision));foreach(var x in new[]{s,host.Current})NewGameWorldTests.At(x,3*86400+1);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));Assert.Equal(fact,LocalSecurity.Known(s.DiagnosticSnapshot(),Site));Assert.False(LocalSecurity.Protected(s.DiagnosticSnapshot(),Site,s.Seconds,s.Revision+1));Assert.Equal(ResultCode.NotAvailable,s.ManageSecurity(new(new("request:remote"),SecurityAction.Observe,new("site:kofu")),s.Revision).Code);}
 [Fact]public void ForgedPayAndForeignGuardAreRejected(){var s=Start();Assert.Equal(ResultCode.NotAvailable,s.ManageSecurity(new(new("request:foreign"),SecurityAction.Assign,Site,new("person:shingen")),s.Revision).Code);Assign(s);var w=s.DiagnosticSnapshot();w.Bandits=w.Bandits! with{Security=w.Bandits.Security!.Select((o,i)=>i==0?o with{Paid=0}:o).ToArray()};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
}
